// ─── File: DesignAssistantDemo.java ───
// Approaches "Design X" top-down: decompose by journey, then
// Requirement → Responsibility → Data → Technology with justified tech.
import java.util.*;
import java.util.logging.*;

public class DesignAssistantDemo {
    private static final Logger log = Logger.getLogger("DESIGN");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("=== Phase 1: scope — mobile banking backend, 10M DAU ===");
        log.info("=== Phase 2: decompose by user journey into components ===");

        List<Component> components = List.of(
            // journey, component, responsibility, readQps, writeQps, datasetGb, mediaHeavy
            new Component("login", "auth", "verify credentials, issue tokens", 20_000, 4_000, 8, false),
            new Component("check-balance", "accounts", "serve balances + history", 90_000, 10_000, 400, false),
            new Component("transfer-money", "transfer", "move funds atomically + fan out events", 5_000, 20_000, 500, false),
            new Component("statements", "documents", "serve PDF statements to global users", 30_000, 500, 2000, true)
        );

        DesignAssistant assistant = new DesignAssistant(5, true, true, 64);
        for (Component c : components) {
            DesignDecision d = assistant.design(c);
            log.info(() -> "── Component: " + c.name() + " (journey: " + c.journey() + ") ──");
            log.info(() -> "   Requirement:    " + c.responsibility());
            log.info(() -> "   Responsibility: owns " + c.name() + " only (single job)");
            log.info(() -> "   Data:           read " + c.readQps() + " / write " + c.writeQps()
                    + " QPS, " + c.datasetGb() + " GB" + (c.mediaHeavy() ? ", media-heavy" : ""));
            log.info(() -> "   Technology:     " + d.technology());
            log.info(() -> "   Justified by:   " + d.justification());
        }
    }
}

