class Component {
    private final String journey, name, responsibility;
    private final int readQps, writeQps, datasetGb; private final boolean mediaHeavy;
    Component(String journey, String name, String responsibility, int readQps, int writeQps, int datasetGb, boolean mediaHeavy) {
        this.journey = journey; this.name = name; this.responsibility = responsibility;
        this.readQps = readQps; this.writeQps = writeQps; this.datasetGb = datasetGb; this.mediaHeavy = mediaHeavy;
    }
    String journey() { return journey; } String name() { return name; }
    String responsibility() { return responsibility; }
    int readQps() { return readQps; } int writeQps() { return writeQps; }
    int datasetGb() { return datasetGb; } boolean mediaHeavy() { return mediaHeavy; }
}

