// ─── assistant/DesignAssistant.java ───
class DesignAssistant {
    private final int cacheRatio; private final boolean queueOnFanout, cdnOnMedia; private final int shardGb;
    DesignAssistant(int cacheRatio, boolean queueOnFanout, boolean cdnOnMedia, int shardGb) {
        this.cacheRatio = cacheRatio; this.queueOnFanout = queueOnFanout;
        this.cdnOnMedia = cdnOnMedia; this.shardGb = shardGb;
    }
    // Start simple (app + relational DB); add tech ONLY at a named bottleneck.
    DesignDecision design(Component c) {
        StringBuilder tech = new StringBuilder("Spring Boot service + PostgreSQL (source of truth)");
        StringBuilder why = new StringBuilder("baseline: simplest thing that works");

        if (c.writeQps() > 0 && c.readQps() / Math.max(1, c.writeQps()) >= cacheRatio) {
            tech.append(" + Redis cache");
            why.append("; read/write ratio ").append(c.readQps() / Math.max(1, c.writeQps()))
               .append(":1 ≥ ").append(cacheRatio).append(" → cache hot reads");
        }
        if (queueOnFanout && c.name().equals("transfer")) {
            tech.append(" + Kafka");
            why.append("; transfer must fan out events to notifications/audit without blocking user");
        }
        if (cdnOnMedia && c.mediaHeavy()) {
            tech.append(" + CDN");
            why.append("; media-heavy + global users → serve at edge, spare origin bandwidth");
        }
        if (c.datasetGb() > shardGb) {
            tech.append(" + sharding");
            why.append("; dataset ").append(c.datasetGb()).append(" GB > ").append(shardGb)
               .append(" GB single-node → shard");
        }
        return new DesignDecision(tech.toString(), why.toString());
    }
}

